use std::collections::HashMap;

fn exec_last_occurrence_position(cafes: &Vec<i8>, cafe: i8) -> usize {
    // Scan through the array and record the last index where `cafe` appears.
    let mut pos = 0;
    for (i, &c) in cafes.iter().enumerate() {
        if c == cafe {
            pos = i;
        }
    }
    pos
}

fn solve(cafes: Vec<i8>) -> i8 {
    // Build a map from each cafe value to its last occurrence index.
    let mut last_pos: HashMap<i8, usize> = HashMap::new();
    for (i, &c) in cafes.iter().enumerate() {
        last_pos.insert(c, i);
    }

    // Initialize with the first element.
    let mut min_cafe = cafes[0];
    let mut min_pos = *last_pos.get(&min_cafe).unwrap();

    // Find the cafe whose last occurrence index is minimal.
    for (&c, &pos) in &last_pos {
        if pos < min_pos {
            min_pos = pos;
            min_cafe = c;
        }
    }

    min_cafe
}

